// Several concrete Service implementations already exist in the codebase
// Requirement: combine logging and caching in different permutations per instance

// Version A: compose lightweight wrappers per behavior
interface Service { execute(): string }
class CoreService implements Service { execute() { return 'core'; } }
class LoggingWrapper implements Service { constructor(private inner: Service) {} execute() { console.log('log'); return this.inner.execute(); } }
class CachingWrapper implements Service { constructor(private inner: Service) {} execute() { /* cache check */ return this.inner.execute(); } }

// Version B: create concrete subclasses for combinations
class ServiceWithLogAndCache extends CoreService { execute() { console.log('log'); /* cache check */ return super.execute(); } }
